// Package pipeline orchestrates the TS, clock, audio and RTP subsystems
// behind the transaction journal and reports one end-to-end metric set.
package pipeline

import (
	"bytes"
	"math/rand"

	"medkernel/audio"
	"medkernel/media"
	"medkernel/rtp"
	"medkernel/ts"

	prtp "github.com/pion/rtp"
)

// Scenario names generated by the fixture builder.
const (
	ScenNormal     = "normal"
	ScenPCRWrap    = "pcr_wrap"
	ScenPCRDrift   = "pcr_drift"
	ScenCCJump     = "cc_jump"
	ScenTruncated  = "truncated"
	ScenPSIVersion = "psi_version"
	ScenRTPLoss    = "rtp_loss"
)

// Fixtures bundles the generated inputs for one run.
type Fixtures struct {
	TS         bytes.Buffer
	PMT        ts.TrackMeta
	AudioPID   uint16
	VideoPID   uint16
	Packets    []ts.Packet // detached packets after a structural parse
	PSIBounds  []ts.Boundary
	TSFaults   []*media.MediaError
	RTPPackets []*prtp.Packet
	RTPWindow  int
	LossPlan   []uint16 // sequence numbers deliberately withheld
}

// Generator builds deterministic, self-contained fixtures from a seed.
type Generator struct {
	rng *rand.Rand
}

// NewGenerator seeds the deterministic generator.
func NewGenerator(seed int64) *Generator { return &Generator{rng: rand.New(rand.NewSource(seed))} }

// BuildTS produces one TS stream plus the requested fault injection.
func (g *Generator) BuildTS(scenario string, packets int) *Fixtures {
	fx := &Fixtures{}
	fx.PMT = ts.TrackMeta{Channels: 2, Layout: audio.LayoutStereo, SampleRate: 48000}
	pmtPID, audioPID, videoPID := uint16(0x1000), uint16(0x1100), uint16(0x1200)
	fx.AudioPID, fx.VideoPID = audioPID, videoPID

	write := func(b []byte) { fx.TS.Write(b) }
	write(ts.BuildPacket(ts.PIDPAT, 0, true, ts.BuildPAT(pmtPID, 0), -1, false))
	write(ts.BuildPacket(pmtPID, 0, true,
		ts.BuildPMT(pmtPID, audioPID, videoPID, 0, fx.PMT, "bt709"), -1, false))

	cc := uint8(0)
	const ptsStep90 = 3600            // 40 ms per frame at the 90 kHz clock
	const pcrStep27 = ptsStep90 * 300 // matching 27 MHz PCR increment
	// PCR-wrap streams start just below the 33-bit boundary so the raw PCR
	// base wraps to a small value at the midpoint; the tracker must expand it
	// back onto a monotonic axis.
	wrapBase := ts27Wrap - int64(packets/2)*pcrStep27
	for i := 0; i < packets; i++ {
		framePTS := uint64(i) * ptsStep90
		pcr := int64(i) * pcrStep27
		if scenario == ScenPCRWrap {
			pcr = wrapBase + int64(i)*pcrStep27
		}
		// A drift fault jumps one PCR far beyond the configured tolerance
		// while the counter still moves forward.
		if scenario == ScenPCRDrift && i == packets/2 {
			pcr += 5 * pcrStep27
		}
		// Each frame emits an audio then a video packet sharing the same PTS,
		// so a healthy stream measures zero A/V deviation on the common axis.
		for _, pid := range []uint16{audioPID, videoPID} {
			payload := ts.BuildPESPayload(framePTS, 4)
			write(ts.BuildPacket(pid, cc, true, payload, pcr, false))
			cc = (cc + 1) & 0x0F
		}
	}

	switch scenario {
	case ScenCCJump:
		// Rewrite the final packet's CC to jump three steps.
		raw := fx.TS.Bytes()
		raw[len(raw)-188+3] = (raw[len(raw)-188+3] & 0xF0) | ((cc + 2) & 0x0F)
	case ScenTruncated:
		fx.TS.Truncate(fx.TS.Len() - 60) // cut the final packet mid-body
	case ScenPSIVersion:
		write(ts.BuildPacket(pmtPID, 1, true,
			ts.BuildPMT(pmtPID, audioPID, videoPID, 1,
				ts.TrackMeta{Channels: 6, Layout: audio.Layout51, SampleRate: 44100},
				"bt2020"), -1, false))
	}
	return fx
}

const ts27Wrap int64 = 1 << 33 * 300 // 27 MHz value at the 33-bit PCR-base boundary

// BuildRTP produces an RTP packet stream with optional loss/reorder injection.
func (g *Generator) BuildRTP(scenario string, count int) *Fixtures {
	fx := &Fixtures{}
	fx.RTPWindow = 8
	withhold := map[uint16]bool{}
	if scenario == ScenRTPLoss {
		// Withhold ~15% of sequence numbers, reorder a few late arrivals.
		for i := 2; i < count; i++ {
			if g.rng.Intn(100) < 15 {
				withhold[uint16(i)] = true
			}
		}
	}
	for i := 0; i < count; i++ {
		seq := uint16(i)
		if withhold[seq] {
			fx.LossPlan = append(fx.LossPlan, seq)
			continue
		}
		fx.RTPPackets = append(fx.RTPPackets, &prtp.Packet{
			Header: prtp.Header{
				SequenceNumber: seq,
				Timestamp:      uint32(i) * 3600,
				SSRC:           4242,
			},
			Payload: []byte{byte(seq >> 8), byte(seq)},
		})
	}
	// Deterministic mild reorder: swap two adjacent non-withheld packets.
	if len(fx.RTPPackets) > 6 {
		fx.RTPPackets[3], fx.RTPPackets[4] = fx.RTPPackets[4], fx.RTPPackets[3]
	}
	return fx
}

// JitterWindow exposes the configured buffer window.
func (fx *Fixtures) JitterWindow() int { return fx.RTPWindow }

// NewJitter builds a jitter buffer sized for these fixtures.
func (fx *Fixtures) NewJitter() *rtp.JitterBuffer {
	w := fx.RTPWindow
	if w == 0 {
		w = 8
	}
	return rtp.NewJitterBuffer(w)
}
